+  "examples": "```json\n{\n  \"name\": \"device name\",\n  \"root\": \"id of root device\",\n  \"parent\": \"id of parent device\", \n  \"children\": [\"ids of child devices\", \"ids of child devices\"],\n  \"extensions\": [\"extention-identifier\", \"extention-identifier2\"],\n```",
