+        "id": {
+          "$ref": "#/definitions/HomieID",
+          "description": "ID of element"
+        }
+      },
+      "required": [
+        "state",
+        "version",
+        "homie",
+        "id"
+      ],
+      "additionalProperties": false
+    },
+    "DeviceState": {
+      "type": "string",
+      "enum": [
+        "init",
+        "ready",
+        "disconnected",
+        "sleeping",
+        "lost",
+        "alert"
